    </div>
  );
}

"use client";

import type { ChatMessagePartProps } from "@/components/control-ui/chat-message";
import { useChatMessageContext } from "@/components/control-ui/hooks/use-chat-message";
import { cn } from "@/components/control-ui/lib/cn";

export type ChatMessageReactionsProps = ChatMessagePartProps<"div">;

export function ChatMessageReactions({ className, "aria-label": ariaLabel = "Reactions", ...props }: ChatMessageReactionsProps) {
  const message = useChatMessageContext();

  return (
    // biome-ignore lint/a11y/useSemanticElements: A reaction strip groups toggle buttons, not form fields.
    <div
      role="group"
      aria-label={ariaLabel}
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="reactions"
      data-layout={message.layout}
      data-role={message.from}
      className={cn("flex flex-wrap items-center", className)}
      {...props}
    />
  );
}

type ChatMessageReactionChip = {
  emoji: string;
  count: number;
  pressed?: boolean;
  label?: string;
};

export type ChatMessageReactionProps =
  | (Omit<ChatMessagePartProps<"button">, "children" | "onClick"> &
      ChatMessageReactionChip & { onPressedChange: (pressed: boolean) => void })
  | (Omit<ChatMessagePartProps<"span">, "children"> &
      ChatMessageReactionChip & {
        /** Omitted for viewers who can see reactions but not add them: the chip renders as static text. */
        onPressedChange?: undefined;
      });

function reactionAttributes(pressed: boolean, className: string | undefined) {
  return {
    "data-control-ui": "chat-message",
    "data-control-family": "chat-message",
    "data-slot": "reaction",
    "data-pressed": pressed ? "" : undefined,
    className: cn("inline-flex items-center", className),
  };
}

function ReactionChipContent({ emoji, count, label }: Required<Omit<ChatMessageReactionChip, "pressed">>) {
  return (
    <>
      <span aria-hidden="true" data-control-ui="chat-message" data-control-family="chat-message" data-slot="reaction-emoji">
        {emoji}
      </span>
      <span aria-hidden="true" className="tabular-nums">
        {count}
      </span>
      <span className="sr-only">{label}</span>
    </>
  );
}

export function ChatMessageReaction(props: ChatMessageReactionProps) {
  const chip = <ReactionChipContent emoji={props.emoji} count={props.count} label={props.label ?? `${props.emoji} ${props.count}`} />;

  if (props.onPressedChange === undefined) {
    const { emoji, count, pressed = false, label, onPressedChange, className, ...spanProps } = props;
    return (
      <span {...reactionAttributes(pressed, className)} {...spanProps}>
        {chip}
      </span>
    );
  }

  const { emoji, count, pressed = false, label, onPressedChange, className, ...buttonProps } = props;
  return (
    <button
      type="button"
      aria-pressed={pressed}
      onClick={() => onPressedChange(!pressed)}
      {...reactionAttributes(pressed, className)}
      {...buttonProps}
    >
      {chip}
    </button>
  );
}

export type ChatMessageReplySummaryProps = ChatMessagePartProps<"button">;

export function ChatMessageReplySummary({ className, type = "button", ...props }: ChatMessageReplySummaryProps) {
  return (
    <button
      type={type}
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="reply-summary"
      className={cn("inline-flex max-w-full items-center self-start text-start", className)}
      {...props}
    />
  );
}

export type ChatMessageRepliesProps = ChatMessagePartProps<"div">;

/** Replies shown in place, nested under the message they answer, as in comment discussions. */
export function ChatMessageReplies({ className, ...props }: ChatMessageRepliesProps) {
  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="replies"
      className={cn("flex flex-col", className)}
      {...props}
    />
  );
}

export type ChatTypingIndicatorProps = ChatMessagePartProps<"div">;

/** A polite status region that stays mounted; pass children only while someone is typing so the change is announced. */
export function ChatTypingIndicator({ className, children, ...props }: ChatTypingIndicatorProps) {
  const someoneIsTyping = children !== null && children !== undefined && children !== false && children !== "";

  return (
    <div
      role="status"
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="root"
      data-kind="typing"
      className={cn("flex min-w-0 items-center", className)}
      {...props}
    >
      {someoneIsTyping ? (
        <>
          <span
            aria-hidden="true"
            data-control-ui="chat-message"
            data-control-family="chat-message"
            data-slot="typing-dots"
            className="inline-flex items-center"
          >
            <span />
            <span />
            <span />
          </span>
          <span className="truncate">{children}</span>
        </>
      ) : null}
    </div>
  );
}

@layer components {
  :where([data-control-family="chat-message"][data-slot="editable"]) {
    min-inline-size: 0;
    max-inline-size: 100%;
  }

  :where([data-control-family="chat-message"][data-slot="content"][data-editable]) {
    position: relative;
    display: grid;
    outline: var(--focus-ring-width) var(--focus-ring-style) transparent;
    outline-offset: calc(var(--focus-ring-width) * -1);
    transition: outline-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="chat-message"][data-slot="content"][data-editable]:focus-within) {
    outline-color: var(--focus-ring);
  }

  :where([data-control-family="chat-message"][data-slot="editable"] :is([data-slot="edit-value"], [data-slot="edit-sizer"])) {
    grid-area: 1 / 1;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    min-inline-size: 0;
  }

  :where([data-control-family="chat-message"][data-slot="editable"] [data-slot="edit-sizer"]) {
    visibility: hidden;
    contain: inline-size;
    min-inline-size: 100%;
    inline-size: 0;
    block-size: 0;
    max-block-size: 40dvh;
    overflow: hidden;
  }

  :where([data-control-family="chat-message"][data-slot="editable"][data-editing] [data-slot="edit-sizer"]) {
    block-size: auto;
  }

  @supports (interpolate-size: allow-keywords) {
    :where([data-control-family="chat-message"][data-slot="editable"] [data-slot="edit-sizer"]) {
      interpolate-size: allow-keywords;
      transition: block-size var(--duration-fast) var(--ease-standard);
    }
  }

  :where([data-control-family="chat-message"][data-slot="editable"] [data-slot="edit-input"]) {
    position: absolute;
    inset: 0;
    box-sizing: border-box;
    inline-size: 100%;
    block-size: 100%;
    min-inline-size: 0;
    margin: 0;
    border: 0;
    padding: inherit;
    resize: none;
    background: transparent;
    color: inherit;
    font: inherit;
    letter-spacing: inherit;
    text-align: inherit;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    scrollbar-width: thin;
    outline: none;
    visibility: hidden;
  }

  :where([data-control-family="chat-message"][data-slot="editable"][data-editing] [data-slot="edit-input"]) {
    visibility: visible;
  }

  :where([data-control-family="chat-message"][data-slot="editable"][data-editing] [data-slot="edit-value"]) {
    visibility: hidden;
  }

  :where([data-control-family="chat-message"][data-slot="editable"] [data-slot="edit-toolbars"]) {
    display: grid;
  }

  :where([data-control-family="chat-message"][data-slot="editable"] [data-slot="edit-toolbar"]) {
    grid-area: 1 / 1;
    min-inline-size: 0;
    visibility: hidden;
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="chat-message"][data-slot="editable"] [data-slot="edit-toolbar"][data-active]) {
    visibility: visible;
    opacity: 1;
  }

  :where([data-control-family="chat-message"][data-slot="editable"] [data-slot="edit-error"]) {
    display: block;
    margin-block-start: calc(var(--spacing) * 1);
    color: var(--destructive);
    font-size: var(--text-caption);
  }

  :where([data-control-family="chat-message"][data-slot="editable"] [data-slot="edit-error"][hidden]) {
    display: none;
  }
}

@layer components {
  :where([data-control-family="chat-message"][data-slot="root"][data-kind="typing"]) {
    gap: calc(var(--spacing) * 2);
    min-block-size: calc(var(--spacing) * 5);
    font-size: var(--text-caption);
    --cui-chat-message-foreground: var(--muted-foreground);
  }

  :where([data-control-family="chat-message"][data-slot="row"][data-continuation]) {
    padding-block-start: calc(var(--spacing) * 0.5);
  }

  :where([data-control-family="chat-message"][data-slot="avatar"][data-continuation]) {
    margin-block-start: 0;
    block-size: calc(var(--spacing) * 5);
    border-color: transparent;
    background: transparent;
  }

  :where([data-control-family="chat-message"][data-slot="avatar"] [data-slot="time"]) {
    font-size: 0.625rem;
    opacity: 0;
    transition-property: opacity;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="chat-message"][data-slot="row"]:hover > [data-slot="avatar"] [data-slot="time"]) {
    opacity: 1;
  }

  :where([data-control-family="chat-message"][data-slot="row"]:focus-within > [data-slot="avatar"] [data-slot="time"]) {
    opacity: 1;
  }

  :where([data-control-family="chat-message"][data-slot="footer"]) {
    margin-block-start: calc(var(--spacing) * 1);
    gap: calc(var(--spacing) * 1.5);
    padding-inline: calc(var(--spacing) * 1);
    font-size: var(--text-caption);
    color: var(--muted-foreground);
  }

  :where([data-control-family="chat-message"][data-slot="footer"][data-state="error"]) {
    color: var(--destructive);
  }

  :where([data-control-family="chat-message"][data-slot="reactions"]) {
    margin-block-start: calc(var(--spacing) * 1.5);
    gap: calc(var(--spacing) * 1);
  }

  :where(
    [data-control-family="chat-message"]:is(
      [data-slot="header"],
      [data-slot="footer"],
      [data-slot="reactions"]
    )[data-layout="bubble"][data-role="user"]
  ) {
    justify-content: flex-end;
  }

  :where([data-control-family="chat-message"][data-slot="footer"][data-layout="flat"]) {
    padding-inline: 0;
  }

  :where([data-control-family="chat-message"][data-slot="reaction"]) {
    gap: calc(var(--spacing) * 1);
    block-size: calc(var(--spacing) * 6);
    padding-inline: calc(var(--spacing) * 2);
    border: var(--cui-chat-message-reaction-border-width) solid var(--cui-chat-message-reaction-border-color);
    border-radius: var(--cui-chat-message-reaction-radius);
    background: var(--cui-chat-message-reaction-background);
    font-size: var(--text-caption);
    font-weight: 500;
    color: var(--muted-foreground);
    transition-property: background-color, border-color, color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="chat-message"][data-slot="reaction"][data-pressed]) {
    border-color: var(--cui-chat-message-reaction-pressed-border-color);
    background: var(--cui-chat-message-reaction-pressed-background);
    color: var(--foreground);
  }

  @media (hover: hover) and (pointer: fine) {
    :where([data-control-family="chat-message"][data-slot="reaction"][aria-pressed]:hover) {
      color: var(--foreground);
    }
  }

  :where([data-control-family="chat-message"][data-slot="reaction-emoji"]) {
    font-size: var(--text-body);
    line-height: 1;
  }

  :where([data-control-family="chat-message"][data-slot="reply-summary"]) {
    margin-block-start: calc(var(--spacing) * 1);
    gap: calc(var(--spacing) * 2);
    padding: calc(var(--spacing) * 1);
    border-radius: var(--radius-md);
    font-size: var(--text-caption);
    color: var(--muted-foreground);
    transition-property: background-color, color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  @media (hover: hover) and (pointer: fine) {
    :where([data-control-family="chat-message"][data-slot="reply-summary"]:hover) {
      background-color: var(--cui-chat-message-row-hover-background);
      color: var(--foreground);
    }
  }

  :where([data-control-family="chat-message"][data-slot="replies"]) {
    margin-block-start: calc(var(--spacing) * 2);
    padding-inline-start: calc(var(--spacing) * 3);
    border-inline-start: 2px solid var(--border);
  }
}

@layer components {
  :where([data-control-family="chat-message"][data-slot="root"]) {
    --cui-chat-message-avatar-radius: 9999px;
    --cui-chat-message-avatar-background: var(--card);
    --cui-chat-message-avatar-border-color: var(--border);
    --cui-chat-message-avatar-border-width: var(--control-rim-width);
    --cui-chat-message-radius: 0px;
    --cui-chat-message-corner-radius: 0px;
    --cui-chat-message-background: transparent;
    --cui-chat-message-background-image: none;
    --cui-chat-message-foreground: var(--foreground);
    --cui-chat-message-border-color: transparent;
    --cui-chat-message-border-width: 0px;
    --cui-chat-message-shadow: none;
    --cui-chat-message-pending-dot-color: var(--muted-foreground);
    --cui-chat-message-pending-dot-size: calc(var(--spacing) * 1.5);
    --cui-chat-message-row-hover-background: oklch(from var(--muted) l c h / 0.6);
    --cui-chat-message-reaction-radius: 9999px;
    --cui-chat-message-reaction-background: oklch(from var(--muted) l c h / 0.7);
    --cui-chat-message-reaction-border-color: transparent;
    --cui-chat-message-reaction-border-width: var(--control-rim-width);
    --cui-chat-message-reaction-pressed-background: oklch(from var(--primary) l c h / 0.14);
    --cui-chat-message-reaction-pressed-border-color: oklch(from var(--primary) l c h / 0.55);
  }

  :where([data-control-family="chat-message"][data-slot="pending"]),
  :where([data-control-family="chat-message"][data-slot="typing-dots"]) {
    gap: var(--cui-chat-message-pending-dot-size);
  }

  :where([data-control-family="chat-message"][data-slot="pending"]) {
    padding-block: calc(var(--spacing) * 2);
  }

  :where([data-control-family="chat-message"][data-slot="pending"] > span),
  :where([data-control-family="chat-message"][data-slot="typing-dots"] > span) {
    inline-size: var(--cui-chat-message-pending-dot-size);
    block-size: var(--cui-chat-message-pending-dot-size);
    border-radius: 9999px;
    background: var(--cui-chat-message-pending-dot-color);
    animation: chat-message-pending calc(var(--duration-slow) * 3) var(--ease-standard) infinite;
  }

  :where([data-control-family="chat-message"][data-slot="pending"] > span:nth-child(2)),
  :where([data-control-family="chat-message"][data-slot="typing-dots"] > span:nth-child(2)) {
    animation-delay: calc(var(--duration-slow) / 2);
  }

  :where([data-control-family="chat-message"][data-slot="pending"] > span:nth-child(3)),
  :where([data-control-family="chat-message"][data-slot="typing-dots"] > span:nth-child(3)) {
    animation-delay: var(--duration-slow);
  }

  @keyframes chat-message-pending {
    0%,
    60%,
    100% {
      opacity: 0.3;
      scale: 0.75;
    }
    30% {
      opacity: 1;
      scale: 1;
    }
  }

  :where([data-control-family="chat-message"][data-slot="row"]) {
    gap: calc(var(--spacing) * 2);
    padding-block: calc(var(--spacing) * 2);
  }

  :where([data-control-family="chat-message"][data-slot="row"][data-density="compact"]) {
    padding-block: calc(var(--spacing) * 1);
  }

  :where([data-control-family="chat-message"][data-slot="row"][data-layout="flat"]) {
    gap: calc(var(--spacing) * 3);
    padding-inline: calc(var(--spacing) * 2);
    border-radius: var(--radius-md);
    transition-property: background-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  @media (hover: hover) and (pointer: fine) {
    :where([data-control-family="chat-message"][data-slot="row"][data-layout="flat"]:hover:not(:has([data-slot="row"]:hover))) {
      background-color: var(--cui-chat-message-row-hover-background);
    }
  }

  :where([data-control-family="chat-message"][data-slot="body"]) {
    flex: 1;
    max-inline-size: 100%;
  }

  :where([data-control-family="chat-message"][data-slot="body"][data-layout="bubble"]:is([data-role="user"], [data-role="participant"])) {
    flex: 0 1 auto;
    max-inline-size: 76%;
  }

  :where([data-control-family="chat-message"][data-slot="avatar"]) {
    margin-block-start: calc(var(--spacing) * 0.5);
    inline-size: calc(var(--spacing) * 6);
    block-size: calc(var(--spacing) * 6);
    border: var(--cui-chat-message-avatar-border-width) solid var(--cui-chat-message-avatar-border-color);
    border-radius: var(--cui-chat-message-avatar-radius);
    background: var(--cui-chat-message-avatar-background);
    font-size: var(--text-caption);
    color: var(--muted-foreground);
  }

  :where([data-control-family="chat-message"][data-slot="avatar"][data-layout="flat"]) {
    inline-size: calc(var(--spacing) * 8);
    block-size: calc(var(--spacing) * 8);
  }

  :where([data-control-family="chat-message"][data-slot="avatar"]:has(> [data-control-family="avatar"])) {
    border-color: transparent;
    background: transparent;
  }

  :where([data-control-family="chat-message"][data-slot="content"]) {
    border: var(--cui-chat-message-border-width) solid var(--cui-chat-message-border-color);
    border-radius: var(--cui-chat-message-radius);
    border-start-end-radius: var(--cui-chat-message-corner-radius);
    background-color: var(--cui-chat-message-background);
    background-image: var(--cui-chat-message-background-image);
    box-shadow: var(--cui-chat-message-shadow);
    color: var(--cui-chat-message-foreground);
    overflow-wrap: break-word;
    font-size: var(--text-body);
    line-height: calc(var(--spacing) * 5);
  }

  :where([data-control-family="chat-message"][data-slot="root"][data-layout="bubble"][data-role="user"]) {
    --cui-chat-message-radius: var(--radius-field);
    --cui-chat-message-corner-radius: var(--radius-lg);
    --cui-chat-message-background: var(--primary);
    --cui-chat-message-foreground: var(--primary-foreground);
    --cui-chat-message-shadow: var(--shadow-sm);
  }

  :where([data-control-family="chat-message"][data-slot="root"][data-layout="bubble"][data-role="participant"]) {
    --cui-chat-message-radius: var(--radius-field);
    --cui-chat-message-corner-radius: var(--radius-field);
    --cui-chat-message-background: var(--muted);
  }

  :where([data-control-family="chat-message"][data-slot="header"][data-role="assistant"][data-state="streaming"]) {
    @apply shimmer-text;
  }

  :where([data-control-family="chat-message"][data-slot="header"]) {
    margin-block-end: calc(var(--spacing) * 1);
    gap: calc(var(--spacing) * 2);
    padding-inline: calc(var(--spacing) * 1);
    font-size: var(--text-caption);
    color: var(--muted-foreground);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="chat-message"][data-slot="header"][data-layout="flat"]) {
    margin-block-end: calc(var(--spacing) * 0.5);
    padding-inline: 0;
  }

  :where([data-control-family="chat-message"][data-slot="author"]) {
    font-weight: 500;
    color: var(--foreground);
  }

  :where([data-control-family="chat-message"][data-slot="author"][data-layout="flat"]) {
    font-size: var(--text-body);
  }

  :where([data-control-family="chat-message"][data-slot="actions"]) {
    margin-block-start: calc(var(--spacing) * 1);
    gap: calc(var(--spacing) * 1);
    opacity: 1;
    transition-property: opacity;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="chat-message"][data-slot="actions"][data-layout="flat"]) {
    position: relative;
    isolation: isolate;
    align-self: flex-start;
    margin-block-start: 0;
    padding: calc(var(--spacing) * 0.5);
  }

  @media (hover: hover) and (pointer: fine) {
    :where([data-control-family="chat-message"][data-slot="actions"]) {
      opacity: 0;
      pointer-events: none;
    }

    :where([data-control-family="chat-message"][data-slot="actions"][data-layout="flat"]) {
      position: absolute;
      z-index: 1;
      inset-block-start: calc(var(--spacing) * -3);
      inset-inline-end: calc(var(--spacing) * 2);
    }

    :where([data-control-family="chat-message"][data-slot="row"]:hover:not(:has([data-slot="row"]:hover)) > [data-slot="actions"]),
    :where(
        [data-control-family="chat-message"][data-slot="row"]:hover:not(:has([data-slot="row"]:hover))
          > [data-slot="body"]
          > [data-slot="actions"]
      ) {
      opacity: 1;
      pointer-events: auto;
    }
  }

  :where(
    [data-control-family="chat-message"][data-slot="row"]:focus-within:not(:has([data-slot="row"]:focus-within)) > [data-slot="actions"]
  ),
  :where(
    [data-control-family="chat-message"][data-slot="row"]:focus-within:not(:has([data-slot="row"]:focus-within))
      > [data-slot="body"]
      > [data-slot="actions"]
  ),
  :where([data-control-family="chat-message"][data-slot="actions"]:has([data-popup-open])) {
    opacity: 1;
    pointer-events: auto;
  }
}

